using System;
using System.Globalization;
using System.Linq;
using System.Net;
using System.Text.Json;

namespace SqlAuditor.Reporting;

internal static class RichHtmlReadoutRenderer
{
    public static string Render(AuditWorkbookModel model, IReadOnlyList<AuditWorkbookModel> estateModels)
    {
        var calculator = new ScoreCalculator();
        var estate = estateModels.Count == 0 ? new[] { model } : estateModels;
        var estateRating = calculator.GetRiskRating(
            estate.Where(server => server.OverallScore.HasValue)
                .Select(server => server.OverallScore!.Value)
                .DefaultIfEmpty()
                .Min());
        var payload = new
        {
            target = model.Target,
            servers = estate.Select(server =>
                new
                {
                    id = server.Target,
                    name = server.Target,
                    score = server.OverallScore,
                    rating = server.OverallRating.Label,
                    validated = server.Items.Count(i => i.IsScored),
                    awaiting = server.Coverage.AwaitingValidation,
                    deterministicCoverage = server.Coverage.DeterministicCoverage.HasValue
                        ? server.Coverage.DeterministicCoverage.Value * 100
                        : (double?)null,
                    databases = server.Databases.Count,
                }),
            generated = model.GeneratedDate,
            workbook = ReportSuiteGenerator.ExcelReportFileName,
            deploymentMode = model.DeploymentMode,
            overallScore = model.OverallScore,
            rating = estateRating.Label,
            coverage = new
            {
                total = estate.Sum(server => server.Coverage.Total),
                deterministic = estate.Sum(server => server.Coverage.Deterministic),
                ai = estate.Sum(server => server.Coverage.AiAssisted),
                manual = estate.Sum(server => server.Coverage.ManualAttestation),
                needsReview = estate.Sum(server => server.Coverage.NeedsReview),
                awaiting = estate.Sum(server => server.Coverage.AwaitingValidation),
                notApplicable = estate.Sum(server => server.Coverage.NotApplicable),
                risks = estate.SelectMany(server => server.Findings)
                    .Select(finding => finding.Item.Id).Distinct(StringComparer.OrdinalIgnoreCase).Count(),
            },
            databases = estate.SelectMany(server => server.Databases.Select(d => new
                {
                    server = server.Target,
                    name = d.Name,
                    sourceId = d.Id,
                }))
                .Select((database, index) => new
                {
                    id = $"EDB{index + 1:000}",
                    database.server,
                    database.name,
                    database.sourceId,
                }),
            areas = model.Areas.Select(a => new
            {
                number = a.Area.Number,
                name = model.AreaName(a.Area.Number),
                weight = a.Area.Weight,
                score = AverageAreaScore(estate, a.Area.Number),
                rating = calculator.GetRiskRating(AverageAreaScore(estate, a.Area.Number)).Label,
                items = estate.SelectMany(server => server.Items).Count(i => i.AreaNumber == a.Area.Number),
                validated = estate.SelectMany(server => server.Items).Count(i => i.AreaNumber == a.Area.Number && i.IsScored),
                priority = estate.SelectMany(server => server.Items)
                    .Where(i => i.AreaNumber == a.Area.Number && i.IsScored && i.Score <= 1)
                    .Select(i => i.Id).Distinct(StringComparer.OrdinalIgnoreCase).Count(),
                serverScores = estate.ToDictionary(
                    server => server.Target,
                    server => server.Areas.First(area => area.Area.Number == a.Area.Number).ScorePercent,
                    StringComparer.OrdinalIgnoreCase),
                categories = a.Categories.Select(c => new
                {
                    id = model.CategoryLabel(c.CategoryId),
                    score = c.ScorePercent,
                    rating = calculator.GetRiskRating(c.ScorePercent).Label,
                    validated = c.ScoredCount,
                    items = c.Items.Count,
                }),
            }),
            controls = estate.SelectMany(server => server.Items.Select(i => new
            {
                server = server.Target,
                id = i.Id,
                area = i.AreaNumber,
                areaName = model.AreaName(i.AreaNumber),
                category = model.CategoryLabel(i.CategoryId),
                title = i.Description,
                status = AuditWorkbookModel.Status(i),
                score = i.IsScored ? i.Score : null,
                producedBy = AuditWorkbookModel.ProducedBy(i),
                severity = AuditWorkbookBuilder.Text(i.Severity),
                rationale = AuditWorkbookBuilder.Text(i.Finding),
                recommendation = AuditWorkbookBuilder.Text(i.Recommendation),
                databases = AuditWorkbookBuilder.DatabasesOf(i),
            })),
            risks = estate.SelectMany(server => server.Findings.Select(f => new
            {
                server = server.Target,
                riskId = f.RiskId,
                id = f.Item.Id,
                area = model.AreaName(f.Item.AreaNumber),
                areaNumber = f.Item.AreaNumber,
                severity = AuditWorkbookBuilder.Text(f.Item.Severity),
                risk = f.Severity.RiskScore,
                likelihood = f.Severity.Likelihood,
                impact = f.Severity.Impact,
                sla = f.Severity.Sla,
                scope = f.Scope,
                impacted = AuditWorkbookBuilder.DatabaseList(f.ImpactedDatabases, AuditWorkbookBuilder.InstanceScope),
                finding = AuditWorkbookBuilder.Text(f.Item.Finding),
                recommendation = AuditWorkbookBuilder.Text(f.Item.Recommendation),
                status = f.Status,
            })),
            accessIssues = estate.SelectMany(server => server.AccessIssues.Select(a => new
            {
                server = server.Target,
                id = a.Item.Id,
                title = AuditWorkbookBuilder.Text(a.Item.Description),
                failureType = a.FailureType,
                status = AuditWorkbookModel.Status(a.Item),
                detail = a.Detail,
            })),
        };

        return Template
            .Replace("__TARGET__", WebUtility.HtmlEncode(model.Target), StringComparison.Ordinal)
            .Replace("__GENERATED__", WebUtility.HtmlEncode(model.GeneratedDate), StringComparison.Ordinal)
            .Replace("__PAYLOAD__", JsonSerializer.Serialize(payload), StringComparison.Ordinal);
    }

    private static double? AverageAreaScore(IEnumerable<AuditWorkbookModel> estate, int areaNumber)
    {
        var scores = estate.SelectMany(server => server.Areas)
            .Where(area => area.Area.Number == areaNumber && area.ScorePercent.HasValue)
            .Select(area => area.ScorePercent!.Value)
            .ToList();
        return scores.Count == 0 ? null : scores.Average();
    }

    private const string Template = """
