<body>
<header class="header"><div class="header-eye">SQL Estate Assessment / OT Server</div><h1>OT Server <span style="color:#ff526a">SQL Assessment</span> Readout</h1><div class="header-sub" id="header-subtitle"></div><div class="header-stats" id="header-stats"></div></header>
<nav class="tabs" aria-label="Assessment sections"><div class="tab-group"><button class="tab active" data-panel="exec">Assessment Summary</button><button class="tab" data-panel="server">Server Comparison</button><button class="tab" data-panel="results">Detailed Results</button><button class="tab" data-panel="risks">Key Risks</button><button class="tab" data-panel="controls">Control Explorer</button><button class="tab" data-panel="recommendations">Recommendations</button><button class="tab" data-panel="timeline">Next Steps &amp; Timeline</button></div><div class="tab-group context"><button class="tab" data-panel="principles">Principles</button><button class="tab" data-panel="scope">Scope &amp; Evidence</button><button class="tab" data-panel="scoring">Scoring</button></div></nav>
<main class="content">
<section class="panel active" id="panel-exec"><div class="page-title">Assessment Summary</div><p class="page-desc">Executive posture, cross-server consistency, and the controls with the greatest operational consequence.</p><div class="hero" id="summary-hero"></div><div class="kpi-band" id="summary-kpis"></div><div class="two-col"><div class="chart-panel"><div class="chart-title">Estate maturity profile</div><div class="chart-sub">Fourteen weighted SQL audit areas against the 76% Good threshold.</div><div id="radar-chart"></div></div><div><div class="chart-title">Top four priorities</div><div class="chart-sub">Evidence-backed priorities across the assessed SQL estate.</div><div class="priority-list" id="top-priorities"></div></div></div><div class="slabel">All audit areas</div><div class="dtable-wrap"><table class="dtable"><thead><tr id="summary-area-head"><th>#</th><th>Audit area</th></tr></thead><tbody id="summary-areas"></tbody></table></div><div class="warn"><h3>Bottom line</h3><p id="summary-conclusion"></p></div></section>
<section class="panel" id="panel-server"><div class="page-title">Server Comparison</div><p class="page-desc">Side-by-side posture, coverage, area variance, and database scope for all assessed SQL Server instances.</p><div class="server-grid" id="server-grid"></div><div class="chart-panel"><div class="chart-title">Server score versus Good threshold</div><div class="chart-sub">The dashed line marks 76%, the beginning of the Good band.</div><div id="server-bars"></div></div><div class="slabel">Area-by-area comparison</div><div class="dtable-wrap"><table class="dtable"><thead><tr id="server-area-head"><th>Area</th></tr></thead><tbody id="server-area-table"></tbody></table></div><div class="slabel">Database inventory</div><div class="dtable-wrap"><table class="dtable"><thead><tr><th>Estate ID</th><th>Server</th><th>Database</th><th>Source-local ID</th></tr></thead><tbody id="database-table"></tbody></table></div></section>
<section class="panel" id="panel-results"><div class="page-title">Detailed Results by Area</div><p class="page-desc">Controls grouped by audit area. Expand an area to inspect findings and recommended actions.</p><div id="area-results"></div></section>
<section class="panel" id="panel-risks"><div class="page-title">Key Risks and Observations</div><p class="page-desc">The complete consolidated action register, filterable by area, severity, server scope, and text.</p><div class="filter-bar"><label>Area<select id="risk-area"></select></label><label>Severity<select id="risk-severity"><option value="">All severities</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></label><label>Scope<select id="risk-scope"><option value="">All scopes</option><option value="shared">Shared</option><option value="specific">Server-specific</option></select></label><label>Search<input id="risk-search" type="search" placeholder="Ref, title, finding..."></label><span class="filter-count" id="risk-count"></span></div><div class="dtable-wrap"><table class="dtable"><thead><tr><th>Ref</th><th>Area</th><th>Severity</th><th>Risk</th><th>Server scope</th><th>Finding / current evidence</th></tr></thead><tbody id="risk-table"></tbody></table></div></section>
<section class="panel" id="panel-controls"><div class="page-title">Control Explorer</div><p class="page-desc" id="controls-description"></p><div class="filter-bar"><label>Area<select id="control-area"></select></label><label>Severity<select id="control-severity"><option value="">All severities</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></label><label>Comparison<select id="control-comparison"><option value="">All comparisons</option><option>Aligned</option><option>Score differs</option><option>Status differs</option><option>Not comparable</option></select></label><label>Search<input id="control-search" type="search" placeholder="Ref, title, rationale..."></label><span class="filter-count" id="control-count"></span></div><div class="dtable-wrap"><table class="dtable"><thead><tr id="control-head"><th>Ref</th><th>Area / category</th><th>Control</th><th>Severity</th></tr></thead><tbody id="control-table"></tbody></table></div></section>
<section class="panel" id="panel-recommendations"><div class="page-title">Recommendations and Modeled Score Opportunity</div><p class="page-desc">Portfolio priorities and source-modeled score changes. Scenarios are independent, denominator-fixed opportunities rather than forecasts.</p><div class="warn info"><h3>How to read the projections</h3><p>The estate projection is the arithmetic mean of independently modeled server scores. Individual gains are not additive; credit requires implementation, evidence, and a rerun.</p></div><div class="chart-panel"><div class="chart-title">Modeled estate score by scenario</div><div class="chart-sub">Current average compared with high-value remediation scenarios and theoretical ceilings.</div><div id="scenario-bars"></div></div><div class="dtable-wrap"><table class="dtable"><thead><tr id="scenario-head"><th>Scenario</th><th>Current avg</th><th>Projected avg</th><th>Gain</th></tr></thead><tbody id="scenario-table"></tbody></table></div><div class="slabel">Priority concentration by area</div><div class="dtable-wrap"><table class="dtable"><thead><tr><th>#</th><th>Area</th><th>Priority actions</th><th>Shared priority</th><th>All actions</th><th>Recommended focus</th></tr></thead><tbody id="recommendation-areas"></tbody></table></div></section>
<section class="panel" id="panel-timeline"><div class="page-title">Next Steps &amp; Timeline</div><p class="page-desc">A sequenced remediation path from immediate risk containment through Good maturity to a 90% estate target, with explicit ownership and evidence gates.</p><div class="warn info"><h3>Planning basis</h3><p>Intermediate scores are denominator-fixed scenarios, not delivery forecasts. Credit is recognized only after remediation evidence is accepted and assessments are rerun.</p></div><div class="chart-panel"><div class="chart-title">Modeled remediation path to 90%</div><div class="chart-sub">Relative delivery windows combine modeled source-server scenarios with the 90% management target.</div><div id="timeline-chart"></div><div class="chart-legend"><span class="legend-key"><span class="legend-line"></span>Current and modeled estate average</span><span class="legend-key"><span class="legend-line target"></span>76% Good threshold</span><span class="legend-key"><span class="legend-line maturity"></span>90% maturity target</span></div></div><div class="slabel">Delivery sequence</div><div class="delivery-grid" id="timeline-grid"></div></section>
<section class="panel" id="panel-principles"><div class="page-title">Assessment Principles</div><p class="page-desc">The SQL Server engineering principles represented by the fourteen audit areas.</p><div class="principle-grid" id="principle-grid"></div></section>
<section class="panel" id="panel-scope"><div class="page-title">Assessment Scope &amp; Evidence</div><p class="page-desc">Target provenance, database identities, and collection limitations.</p><div class="section" id="scope-summary"></div><div class="slabel">Open access exceptions</div><div class="dtable-wrap"><table class="dtable"><thead><tr><th>Ref</th><th>Title</th><th>Failure type</th><th>Status</th><th>Detail</th></tr></thead><tbody id="access-table"></tbody></table></div></section>
<section class="panel" id="panel-scoring"><div class="page-title">Assessment Scoring and Criteria</div><p class="page-desc">Only validated controls contribute to category, area, and weighted overall scores.</p><div class="hero" id="scoring-hero"></div><div class="slabel">Control score scale</div><div class="dtable-wrap"><table class="dtable"><thead><tr><th>Score</th><th>Meaning</th><th>Treatment</th></tr></thead><tbody><tr><td><span class="chip s0">0</span></td><td>Not implemented / ineffective</td><td>Priority remediation</td></tr><tr><td><span class="chip s1">1</span></td><td>Partially implemented / major gaps</td><td>Strengthen and verify</td></tr><tr><td><span class="chip s2">2</span></td><td>Implemented / improvement remains</td><td>Targeted improvement</td></tr><tr><td><span class="chip s3">3</span></td><td>Best practice / fully implemented</td><td>Maintain evidence</td></tr><tr><td><span class="chip sna">-</span></td><td>Pending, inaccessible, or N/A</td><td>Excluded from arithmetic</td></tr></tbody></table></div></section>
</main><footer class="footer">SQL Estate Audit &nbsp;|&nbsp; Evidence from __TARGET__ &nbsp;|&nbsp; Internal / Confidential</footer>
<script>
'use strict';
const DATA=__PAYLOAD__;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pct=v=>Number.isFinite(Number(v))?Number(v).toFixed(1)+'%':'-';const chip=s=>Number.isFinite(Number(s))?'<span class="chip s'+s+'">'+s+'</span>':'<span class="chip sna">-</span>';const badge=s=>'<span class="badge badge-'+String(s||'gray').toLowerCase()+'">'+esc(s||'Not rated')+'</span>';
document.querySelectorAll('.tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===tab));document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id==='panel-'+tab.dataset.panel));window.scrollTo({top:0,behavior:'smooth'})}));
if(false){const estateAverage=DATA.servers.reduce((sum,s)=>sum+(Number(s.score)||0),0)/Math.max(DATA.servers.length,1);const priorityActions=DATA.risks.filter(r=>r.severity==='Critical'||r.severity==='High').length;document.getElementById('header-subtitle').textContent='A consolidated, evidence-backed view of '+DATA.servers.map(s=>s.name).join(', ')+'. Scores remain server-specific; estate posture follows the available assessment evidence.';const stats=[[DATA.servers.length,'Servers'],[DATA.databases.length,'Databases'],[pct(estateAverage),'Average score'],[DATA.rating,'Estate rating'],[priorityActions,'Priority actions']];document.getElementById('header-stats').innerHTML=stats.map(x=>'<div class="hstat"><b>'+esc(x[0])+'</b><span>'+esc(x[1])+'</span></div>').join('');
const hero='<div class="hero-score">'+pct(estateAverage)+'</div><div>'+badge(DATA.rating)+'<div class="hero-meta">Informational estate average &middot; '+DATA.servers.length+' SQL server(s) &middot; '+DATA.databases.length+' database(s) &middot; '+DATA.risks.length+' unique action controls</div></div>';document.getElementById('summary-hero').innerHTML=hero;document.getElementById('scoring-hero').innerHTML=hero;
const validated=DATA.servers.reduce((sum,s)=>sum+s.validated,0),areasAtGood=DATA.areas.filter(a=>(a.score||0)>75).length,weak=DATA.controls.filter(c=>c.score===0||c.score===1).length;const kpis=[[validated,'Validated outcomes'],[DATA.coverage.deterministic,'Deterministic controls'],[weak,'Weak controls'],[DATA.coverage.risks,'Active actions'],[DATA.coverage.awaiting,'Awaiting validation'],[areasAtGood+' / '+DATA.areas.length,'Areas at Good'],[priorityActions,'Critical / High'],[DATA.coverage.notApplicable,'Not applicable']];document.getElementById('summary-kpis').innerHTML=kpis.map(x=>'<div class="kpi"><div class="kpi-value">'+x[0]+'</div><div class="kpi-label">'+x[1]+'</div></div>').join('');
const chartColumn=(label,value)=>'<div class="maturity-col"><div class="maturity-value">'+pct(value)+'</div><div class="maturity-bar" style="height:'+Math.max(1,value||0)+'%"></div><div class="maturity-label">'+esc(label)+'</div></div>';document.getElementById('area-bars').innerHTML=DATA.areas.map(a=>chartColumn('A'+a.number+' '+a.name.split(' ')[0],a.score)).join('');const serverHead=DATA.servers.map(s=>'<th>'+esc(s.name)+' score</th>').join('');document.getElementById('summary-area-head').innerHTML='<th>#</th><th>Audit area</th>'+serverHead+'<th>Estate avg</th><th>Rating</th><th>Priority</th><th>Details</th>';document.getElementById('summary-areas').innerHTML=DATA.areas.map(a=>'<tr><td>'+a.number+'</td><td><strong>'+esc(a.name)+'</strong></td>'+DATA.servers.map(s=>'<td>'+pct(a.serverScores[s.id])+'</td>').join('')+'<td><strong>'+pct(a.score)+'</strong></td><td>'+badge(a.rating)+'</td><td>'+a.priority+'</td><td><button class="jump" data-area="'+a.number+'">View details &rarr;</button></td></tr>').join('');
document.getElementById('top-priorities').innerHTML=DATA.risks.slice(0,4).map(r=>'<article class="priority"><h3>'+esc(r.id+' - '+r.area)+'</h3><p>'+esc(r.finding)+'</p></article>').join('')||'<div class="empty">No active priorities.</div>';document.getElementById('summary-conclusion').textContent=DATA.overallScore>=76?'The assessed target is in the Good maturity band. Maintain evidence and address remaining findings.':'The assessed target remains below the 76% Good threshold. Prioritize Critical and High findings, then rerun the assessment to verify improvement.';
document.querySelectorAll('.jump').forEach(b=>b.addEventListener('click',()=>{document.querySelector('[data-panel="results"]').click();const section=document.querySelectorAll('.area-sec')[Number(b.dataset.area)-1];section?.classList.add('expanded');section?.scrollIntoView({behavior:'smooth'})}));document.getElementById('server-grid').innerHTML=DATA.servers.map(s=>'<article class="server-card"><h3>'+esc(s.name)+'</h3><div class="server-score">'+pct(s.score)+'</div>'+badge(s.rating)+'<div class="meter"><span style="width:'+Math.max(0,s.score||0)+'%"></span></div><div class="server-facts"><div class="server-fact"><b>'+s.validated+'</b><span>Validated</span></div><div class="server-fact"><b>'+s.awaiting+'</b><span>Awaiting</span></div><div class="server-fact"><b>'+pct(s.deterministicCoverage)+'</b><span>Deterministic</span></div></div></article>').join('');document.getElementById('server-bars').innerHTML=DATA.servers.map(s=>chartColumn(s.name,s.score)).join('');document.getElementById('server-area-head').innerHTML='<th>#</th><th>Area</th>'+DATA.servers.map(s=>'<th>'+esc(s.name)+'</th>').join('')+'<th>Estate avg</th><th>Rating</th><th>Priority</th>';document.getElementById('server-area-table').innerHTML=DATA.areas.map(a=>'<tr><td>'+a.number+'</td><td><strong>'+esc(a.name)+'</strong></td>'+DATA.servers.map(s=>'<td>'+pct(a.serverScores[s.id])+'</td>').join('')+'<td>'+pct(a.score)+'</td><td>'+badge(a.rating)+'</td><td>'+a.priority+'</td></tr>').join('');document.getElementById('database-table').innerHTML=DATA.databases.length?DATA.databases.map(d=>'<tr><td>'+esc(d.id)+'</td><td>'+esc(d.server)+'</td><td>'+esc(d.name)+'</td></tr>').join(''):'<tr><td colspan="3" class="empty">No database-scoped evidence was recorded.</td></tr>';
document.getElementById('area-results').innerHTML=DATA.areas.filter(a=>a.items).map(a=>{const rows=DATA.controls.filter(c=>c.area===a.number).map(c=>'<tr><td>'+esc(c.id)+'</td><td>'+esc(c.title)+'</td><td>'+esc(c.status)+'</td><td>'+chip(c.score)+'</td><td>'+badge(c.severity)+'</td><td>'+esc(c.rationale)+'</td><td>'+esc(c.recommendation)+'</td></tr>').join('');return '<section class="area-sec"><div class="area-head">Area '+a.number+': '+esc(a.name)+'<span class="area-meta">'+pct(a.score)+' &middot; '+a.validated+' validated</span></div><div class="area-content"><div class="dtable-wrap"><table class="dtable"><thead><tr><th>Ref</th><th>Control</th><th>Status</th><th>Score</th><th>Severity</th><th>Finding</th><th>Recommendation</th></tr></thead><tbody>'+rows+'</tbody></table></div></div></section>'}).join('');document.querySelectorAll('.area-head').forEach(h=>h.addEventListener('click',()=>h.parentElement.classList.toggle('expanded')));
function fillSelect(id,values,label){const e=document.getElementById(id);e.innerHTML='<option value="">All '+label+'</option>'+values.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('')}fillSelect('risk-area',DATA.areas.map(a=>a.number),'areas');fillSelect('control-area',DATA.areas.map(a=>a.number),'areas');fillSelect('control-status',[...new Set(DATA.controls.map(c=>c.status))].sort(),'statuses');
function renderRisks(){const area=document.getElementById('risk-area').value,severity=document.getElementById('risk-severity').value,q=document.getElementById('risk-search').value.toLowerCase();const rows=DATA.risks.filter(r=>(!area||String(r.areaNumber)===area)&&(!severity||r.severity===severity)&&(!q||(r.id+' '+r.finding+' '+r.recommendation).toLowerCase().includes(q)));document.getElementById('risk-count').textContent=rows.length+' of '+DATA.risks.length;document.getElementById('risk-table').innerHTML=rows.map(r=>'<tr><td>'+esc(r.riskId)+'</td><td>'+esc(r.server)+'</td><td>'+esc(r.id)+'</td><td>'+esc(r.area)+'</td><td>'+badge(r.severity)+'</td><td>'+r.risk+'</td><td>'+esc(r.finding)+'</td><td>'+esc(r.recommendation)+'</td></tr>').join('')||'<tr><td colspan="8" class="empty">No risks match the current filters.</td></tr>'}['risk-area','risk-severity','risk-search'].forEach(id=>document.getElementById(id).addEventListener('input',renderRisks));renderRisks();
function renderControls(){const area=document.getElementById('control-area').value,status=document.getElementById('control-status').value,q=document.getElementById('control-search').value.toLowerCase();const rows=DATA.controls.filter(c=>(!area||String(c.area)===area)&&(!status||c.status===status)&&(!q||(c.id+' '+c.title+' '+c.rationale).toLowerCase().includes(q)));document.getElementById('control-count').textContent=rows.length+' of '+DATA.controls.length;document.getElementById('control-table').innerHTML=rows.map(c=>'<tr><td>'+esc(c.server)+'</td><td>'+esc(c.id)+'</td><td>'+esc(c.areaName+' / '+c.category)+'</td><td>'+esc(c.title)+'</td><td>'+esc(c.status)+'</td><td>'+chip(c.score)+'</td><td>'+esc(c.producedBy)+'</td><td>'+badge(c.severity)+'</td><td>'+esc(c.rationale)+'</td></tr>').join('')||'<tr><td colspan="9" class="empty">No controls match the current filters.</td></tr>'}['control-area','control-status','control-search'].forEach(id=>document.getElementById(id).addEventListener('input',renderControls));renderControls();
document.getElementById('recommendation-table').innerHTML=DATA.risks.map((r,i)=>'<tr><td>'+(i+1)+'</td><td>'+esc(r.id)+'</td><td>'+esc(r.area)+'</td><td>'+badge(r.severity)+'</td><td>'+esc(r.sla)+'</td><td>'+esc(r.recommendation)+'</td></tr>').join('')||'<tr><td colspan="6" class="empty">No remediation is outstanding.</td></tr>';
const windows=[['0-7 days','Contain critical risk','Critical findings',DATA.risks.filter(r=>r.severity==='Critical').length],['30 days','Close high risks','High findings',DATA.risks.filter(r=>r.severity==='High').length],['90 days','Strengthen controls','Medium findings',DATA.risks.filter(r=>r.severity==='Medium').length],['Next cycle','Sustain maturity','Low findings',DATA.risks.filter(r=>r.severity==='Low').length]];document.getElementById('timeline-grid').innerHTML=windows.map(w=>'<article class="step"><strong>'+esc(w[0]+' - '+w[1])+'</strong><span>'+w[3]+' '+esc(w[2].toLowerCase())+' to address, evidence, and reassess.</span></article>').join('');}

const average=values=>{const valid=values.map(Number).filter(Number.isFinite);return valid.length?valid.reduce((sum,value)=>sum+value,0)/valid.length:null};
const severityRank={Critical:4,High:3,Medium:2,Low:1};
const rate=value=>value>=90?'Excellent':value>=76?'Good':value>=51?'Moderate':'High Risk';
const serverByTarget=target=>DATA.servers.find(server=>server.id===target||server.name===target);
const estateAverage=average(DATA.servers.map(server=>server.score))||0;
const groupedControls=new Map();
DATA.controls.forEach(control=>{if(!groupedControls.has(control.id))groupedControls.set(control.id,{ref:control.id,area:control.area,areaName:control.areaName,category:control.category,title:control.title,severity:control.severity,servers:{}});const item=groupedControls.get(control.id);if((severityRank[control.severity]||0)>(severityRank[item.severity]||0))item.severity=control.severity;const server=serverByTarget(control.server);if(server)item.servers[server.id]=control});
const controls=[...groupedControls.values()].map(control=>{const outcomes=DATA.servers.map(server=>control.servers[server.id]).filter(Boolean);let comparison='Not comparable';if(outcomes.length>1){const scores=new Set(outcomes.map(item=>item.score));const statuses=new Set(outcomes.map(item=>item.status));comparison=statuses.size>1?'Status differs':scores.size>1?'Score differs':'Aligned'}return {...control,comparison}});
const groupedActions=new Map();
DATA.risks.forEach(risk=>{if(!groupedActions.has(risk.id))groupedActions.set(risk.id,{ref:risk.id,area:risk.areaNumber,areaName:risk.area,title:risk.title,severity:risk.severity,risk:risk.risk,recommendation:risk.recommendation,findings:[],servers:[]});const item=groupedActions.get(risk.id);if((severityRank[risk.severity]||0)>(severityRank[item.severity]||0))item.severity=risk.severity;const server=serverByTarget(risk.server);if(server&&!item.servers.some(value=>value.id===server.id))item.servers.push(server);item.findings.push({server:server?.name||risk.server,text:risk.finding})});
const actions=[...groupedActions.values()].map(action=>({...action,shared:DATA.servers.length>1&&action.servers.length===DATA.servers.length})).sort((left,right)=>(severityRank[right.severity]||0)-(severityRank[left.severity]||0)||right.risk-left.risk||left.ref.localeCompare(right.ref));
const priorityActions=actions.filter(action=>severityRank[action.severity]>=3).length;
const assessedAreas=DATA.areas.filter(area=>Number.isFinite(Number(area.score)));
const areasAtGood=assessedAreas.filter(area=>area.score>=76).length;
const weakControls=DATA.controls.filter(control=>control.score===0||control.score===1).length;
const validated=DATA.servers.reduce((sum,server)=>sum+server.validated,0);
const areaActionCount=area=>actions.filter(action=>action.area===area.number).length;
const areaPriorityCount=area=>actions.filter(action=>action.area===area.number&&severityRank[action.severity]>=3).length;
const areaSharedPriority=area=>actions.filter(action=>action.area===area.number&&action.shared&&severityRank[action.severity]>=3).length;
const scoreChip=(score,status)=>Number.isFinite(Number(score))?chip(score):'<span class="chip sna">-</span>';

document.getElementById('header-subtitle').textContent='A consolidated, evidence-backed view of '+DATA.servers.map(server=>server.name).join(', ')+'. Scores remain server-specific; estate posture follows the available assessment evidence.';
const headerStats=[[DATA.servers.length,'Servers'],[DATA.databases.length,'Databases'],[pct(estateAverage),'Average score'],[DATA.rating,'Estate rating'],[priorityActions,'Priority actions']];
document.getElementById('header-stats').innerHTML=headerStats.map(item=>`<div class="hstat"><b>${esc(item[0])}</b><span>${esc(item[1])}</span></div>`).join('');
const hero=`<div class="hero-score">${pct(estateAverage)}</div><div>${badge(DATA.rating)}<div class="hero-meta">Informational estate average &middot; ${DATA.servers.length} SQL server(s) &middot; ${DATA.databases.length} database(s) &middot; ${actions.length} unique action controls</div></div>`;
document.getElementById('summary-hero').innerHTML=hero;document.getElementById('scoring-hero').innerHTML=hero;
const kpis=[[validated,'Validated outcomes'],[DATA.coverage.deterministic,'Deterministic controls'],[weakControls,'Weak outcomes'],[actions.length,'Active actions'],[DATA.coverage.awaiting,'Awaiting validation'],[`${areasAtGood} / ${assessedAreas.length}`,'Areas at Good'],[priorityActions,'Critical / High'],[DATA.coverage.notApplicable,'Not applicable']];
document.getElementById('summary-kpis').innerHTML=kpis.map(item=>`<div class="kpi"><div class="kpi-value">${item[0]}</div><div class="kpi-label">${item[1]}</div></div>`).join('');

function renderRadar(){const width=680,height=430,cx=340,cy=208,radius=155,count=DATA.areas.length,point=(index,value)=>{const angle=-Math.PI/2+index*2*Math.PI/count;return [cx+Math.cos(angle)*radius*value/100,cy+Math.sin(angle)*radius*value/100]};let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Estate maturity radar chart">`;[25,50,75,100].forEach(level=>{const points=DATA.areas.map((_,index)=>point(index,level).join(',')).join(' ');svg+=`<polygon points="${points}" fill="none" stroke="#dce3e8"/><text x="${cx+4}" y="${cy-radius*level/100+11}" font-size="9" fill="#84909a">${level}</text>`});DATA.areas.forEach((area,index)=>{const outer=point(index,100),label=point(index,119);svg+=`<line x1="${cx}" y1="${cy}" x2="${outer[0]}" y2="${outer[1]}" stroke="#e4e9ed"/><text x="${label[0]}" y="${label[1]}" text-anchor="middle" font-size="9" fill="#52606d">A${area.number} ${esc(area.name.split(' ')[0])}</text>`});const threshold=DATA.areas.map((_,index)=>point(index,76).join(',')).join(' '),values=DATA.areas.map((area,index)=>point(index,Number(area.score)||0).join(',')).join(' ');svg+=`<polygon points="${threshold}" fill="none" stroke="#e31837" stroke-width="2" stroke-dasharray="6 4"/><polygon points="${values}" fill="rgba(25,103,163,.2)" stroke="#1967a3" stroke-width="3"/>`;DATA.areas.forEach((area,index)=>{const dot=point(index,Number(area.score)||0);svg+=`<circle cx="${dot[0]}" cy="${dot[1]}" r="3" fill="#1967a3"><title>${esc(area.name)}: ${pct(area.score)}</title></circle>`});document.getElementById('radar-chart').innerHTML=svg+'</svg>'}

const summaryHead=DATA.servers.map(server=>`<th>${esc(server.name)} score</th>`).join('');document.getElementById('summary-area-head').innerHTML=`<th>#</th><th>Audit area</th>${summaryHead}<th>Estate avg</th><th>Rating</th><th>Priority</th><th>Details</th>`;
document.getElementById('summary-areas').innerHTML=DATA.areas.map(area=>`<tr><td>${area.number}</td><td><strong>${esc(area.name)}</strong></td>${DATA.servers.map(server=>`<td>${pct(area.serverScores[server.id])}</td>`).join('')}<td><strong>${pct(area.score)}</strong></td><td>${badge(area.rating)}</td><td>${areaPriorityCount(area)}</td><td><button class="jump" data-area="${area.number}">View details &rarr;</button></td></tr>`).join('');
document.getElementById('top-priorities').innerHTML=actions.slice(0,4).map(action=>`<article class="priority"><h3>${esc(action.ref)} - ${esc(action.areaName)}</h3><p>${esc(action.title)}: ${esc(action.findings[0]?.text||'Evidence review required.')}</p></article>`).join('')||'<div class="empty">No active priorities.</div>';
document.getElementById('summary-conclusion').textContent=estateAverage>=76?'The estate average is in the Good maturity band. Maintain evidence and address remaining findings without allowing the average to hide a weaker server.':'The estate remains below the 76% Good threshold. Prioritize Critical and High controls, collect closure evidence, and rerun each server assessment.';
document.querySelectorAll('.jump').forEach(button=>button.addEventListener('click',()=>{document.querySelector('[data-panel="results"]').click();const section=document.querySelectorAll('.area-sec')[Number(button.dataset.area)-1];section?.classList.add('expanded');section?.scrollIntoView({behavior:'smooth'})}));

document.getElementById('server-grid').innerHTML=DATA.servers.map(server=>`<article class="server-card"><h3>${esc(server.name)}</h3><div class="server-score">${pct(server.score)}</div>${badge(server.rating)}<div class="meter"><span style="width:${Math.max(0,server.score||0)}%"></span></div><div class="server-facts"><div class="server-fact"><b>${server.validated}</b><span>Validated</span></div><div class="server-fact"><b>${server.awaiting}</b><span>Awaiting</span></div><div class="server-fact"><b>${pct(server.deterministicCoverage)}</b><span>Deterministic</span></div></div></article>`).join('');
function horizontalBars(elementId,rows,max=100){const width=980,left=190,right=65,rowHeight=43,height=35+rows.length*rowHeight+35,plot=width-left-right;let svg=`<svg viewBox="0 0 ${width} ${height}">`;[0,25,50,75,100].forEach(tick=>{const x=left+plot*tick/max;svg+=`<line x1="${x}" y1="15" x2="${x}" y2="${height-28}" stroke="#e0e5ea"/><text x="${x}" y="${height-8}" text-anchor="middle" font-size="10" fill="#75818c">${tick}%</text>`});const threshold=left+plot*76/max;svg+=`<line x1="${threshold}" y1="15" x2="${threshold}" y2="${height-28}" stroke="#e31837" stroke-width="2" stroke-dasharray="6 4"/>`;rows.forEach((row,index)=>{const y=23+index*rowHeight;svg+=`<text x="${left-10}" y="${y+16}" text-anchor="end" font-size="11" fill="#40505e">${esc(row.label)}</text><rect x="${left}" y="${y}" width="${plot*Math.max(0,row.value)/max}" height="23" fill="#1967a3"/><text x="${left+plot*Math.max(0,row.value)/max+7}" y="${y+16}" font-size="10" font-weight="700">${pct(row.value)}</text>`});document.getElementById(elementId).innerHTML=svg+'</svg>'}
horizontalBars('server-bars',DATA.servers.map(server=>({label:server.name,value:server.score})));
document.getElementById('server-area-head').innerHTML='<th>Area</th>'+DATA.servers.map(server=>`<th>${esc(server.name)}</th>`).join('')+'<th>Estate avg</th><th>Spread</th><th>Rating</th><th>Priority</th>';
document.getElementById('server-area-table').innerHTML=DATA.areas.map(area=>{const values=DATA.servers.map(server=>Number(area.serverScores[server.id])).filter(Number.isFinite),spread=values.length>1?Math.max(...values)-Math.min(...values):null;return `<tr><td><strong>${area.number}. ${esc(area.name)}</strong></td>${DATA.servers.map(server=>`<td>${pct(area.serverScores[server.id])}</td>`).join('')}<td><strong>${pct(area.score)}</strong></td><td>${spread===null?'Not comparable':spread.toFixed(1)+' pp'}</td><td>${badge(area.rating)}</td><td>${areaPriorityCount(area)}</td></tr>`}).join('');
