document.getElementById('area-results').innerHTML=DATA.areas.filter(area=>area.items).map(area=>{const rows=controls.filter(control=>control.area===area.number).map(control=>`<tr><td>${esc(control.ref)}</td><td>${esc(control.title)}</td>${DATA.servers.map(server=>{const item=control.servers[server.id];return `<td>${item?esc(item.status):'Not assessed'}</td><td>${scoreChip(item?.score,item?.status)}</td>`}).join('')}<td>${badge(control.severity)}</td><td>${esc(Object.values(control.servers)[0]?.recommendation||'')}</td></tr>`).join('');return `<section class="area-sec"><div class="area-head">Area ${area.number}: ${esc(area.name)}<span class="area-meta">${pct(area.score)} &middot; ${area.items} controls</span></div><div class="area-content"><div class="dtable-wrap"><table class="dtable"><thead><tr><th>Ref</th><th>Control</th>${DATA.servers.map(server=>`<th>${esc(server.name)} status</th><th>Score</th>`).join('')}<th>Severity</th><th>Recommendation</th></tr></thead><tbody>${rows}</tbody></table></div></div></section>`}).join('');document.querySelectorAll('.area-head').forEach(head=>head.addEventListener('click',()=>head.parentElement.classList.toggle('expanded')));
function fillAreaSelect(id){document.getElementById(id).innerHTML='<option value="">All areas</option>'+DATA.areas.map(area=>`<option value="${area.number}">${area.number}. ${esc(area.name)}</option>`).join('')}
fillAreaSelect('risk-area');fillAreaSelect('control-area');
function renderRisks(){const area=document.getElementById('risk-area').value,severity=document.getElementById('risk-severity').value,scope=document.getElementById('risk-scope').value,search=document.getElementById('risk-search').value.toLowerCase();const rows=actions.filter(action=>(!area||String(action.area)===area)&&(!severity||action.severity===severity)&&(!scope||(scope==='shared'?action.shared:!action.shared))&&(!search||`${action.ref} ${action.title} ${action.findings.map(item=>item.text).join(' ')}`.toLowerCase().includes(search)));document.getElementById('risk-count').textContent=`Showing ${rows.length} of ${actions.length}`;document.getElementById('risk-table').innerHTML=rows.map(action=>`<tr><td><strong>${esc(action.ref)}</strong></td><td>${action.area}. ${esc(action.areaName)}</td><td>${badge(action.severity)}</td><td>${action.risk}</td><td>${action.shared?'<span class="badge badge-low">Shared</span>':action.servers.map(server=>esc(server.name)).join(', ')}</td><td><strong>${esc(action.title)}</strong>${action.findings.map(item=>`<div class="evidence-box"><b>${esc(item.server)}</b><br>${esc(item.text)}</div>`).join('')}<details class="evidence-detail"><summary>Recommendation</summary><div class="evidence-box">${esc(action.recommendation)}</div></details></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No actions match these filters.</td></tr>'}
['risk-area','risk-severity','risk-scope','risk-search'].forEach(id=>document.getElementById(id).addEventListener('input',renderRisks));renderRisks();
document.getElementById('controls-description').textContent=`${controls.length} unique controls with adjacent outcomes for ${DATA.servers.length} assessed server${DATA.servers.length===1?'':'s'}, comparison state, and evidence rationale.`;
document.getElementById('control-head').innerHTML='<th>Ref</th><th>Area / category</th><th>Control</th><th>Severity</th>'+DATA.servers.map(server=>`<th>${esc(server.name)}</th>`).join('')+'<th>Comparison</th>';
function renderControls(){const area=document.getElementById('control-area').value,severity=document.getElementById('control-severity').value,comparison=document.getElementById('control-comparison').value,search=document.getElementById('control-search').value.toLowerCase();const rows=controls.filter(control=>(!area||String(control.area)===area)&&(!severity||control.severity===severity)&&(!comparison||control.comparison===comparison)&&(!search||`${control.ref} ${control.title} ${control.category} ${Object.values(control.servers).map(item=>item.rationale).join(' ')}`.toLowerCase().includes(search)));document.getElementById('control-count').textContent=`Showing ${rows.length} of ${controls.length}`;document.getElementById('control-table').innerHTML=rows.map(control=>`<tr><td><strong>${esc(control.ref)}</strong></td><td>${control.area}. ${esc(control.category)}</td><td><strong>${esc(control.title)}</strong><details class="evidence-detail"><summary>Evidence rationale</summary>${DATA.servers.map(server=>`<div class="evidence-box"><b>${esc(server.name)}</b><br>${esc(control.servers[server.id]?.rationale||'Not assessed')}</div>`).join('')}</details></td><td>${badge(control.severity)}</td>${DATA.servers.map(server=>{const result=control.servers[server.id];return `<td>${scoreChip(result?.score,result?.status)}<div style="font-size:9px;color:#76828e">${esc(result?.status||'Not assessed')}</div></td>`}).join('')}<td>${badge(control.comparison==='Aligned'?'Good':control.comparison==='Not comparable'?'Gray':'Medium')}<div style="font-size:9px">${esc(control.comparison)}</div></td></tr>`).join('')||`<tr><td colspan="${DATA.servers.length+5}" class="empty">No controls match these filters.</td></tr>`}
['control-area','control-severity','control-comparison','control-search'].forEach(id=>document.getElementById(id).addEventListener('input',renderControls));renderControls();

function modeledScore(server,transform){const source=DATA.controls.filter(control=>serverByTarget(control.server)?.id===server.id&&Number.isFinite(Number(control.score))),byArea=new Map();source.forEach(control=>{if(!byArea.has(control.area))byArea.set(control.area,[]);byArea.get(control.area).push(transform(control))});let weighted=0,totalWeight=0;DATA.areas.forEach(area=>{const values=byArea.get(area.number);if(!values?.length)return;weighted+=(average(values)/3)*100*area.weight;totalWeight+=area.weight});return totalWeight?weighted/totalWeight:server.score}
function scenario(name,assumption,predicate,limit){const projected={};const moved={};DATA.servers.forEach(server=>{const candidates=DATA.controls.filter(control=>serverByTarget(control.server)?.id===server.id&&Number.isFinite(Number(control.score))&&control.score<3&&predicate(control)).sort((a,b)=>(severityRank[b.severity]||0)-(severityRank[a.severity]||0)||a.score-b.score).slice(0,limit||Number.MAX_SAFE_INTEGER),ids=new Set(candidates.map(control=>control.id));const baseline=modeledScore(server,control=>control.score),changed=modeledScore(server,control=>ids.has(control.id)?3:control.score);projected[server.id]=Math.min(100,server.score+changed-baseline);moved[server.id]=ids.size});const value=average(Object.values(projected))||estateAverage;return {name,assumption,projected:value,gain:Math.max(0,value-estateAverage),serverProjected:projected,moved}}
const scenarios=[scenario('Close Critical risks','Raise every scored Critical action control to 3.',control=>control.severity==='Critical'),scenario('Close Critical and High risks','Raise every scored Critical/High action control to 3.',control=>severityRank[control.severity]>=3),scenario('Top 10 controls per server','Raise each server’s ten highest-priority weak controls to 3.',()=>true,10),scenario('Close all score 0 controls','Raise every validated score-zero control to 3.',control=>control.score===0),scenario('Close all score 0-1 controls','Raise every validated score-zero or score-one control to 3.',control=>control.score<=1)];
document.getElementById('scenario-head').innerHTML='<th>Scenario</th><th>Current avg</th><th>Projected avg</th><th>Gain</th>'+DATA.servers.map(server=>`<th>${esc(server.name)} projected</th>`).join('')+'<th>Controls moved to 3</th>';
document.getElementById('scenario-table').innerHTML=scenarios.map(row=>`<tr><td><strong>${esc(row.name)}</strong><div style="font-size:10px;color:#77838e">${esc(row.assumption)}</div></td><td>${pct(estateAverage)}</td><td><strong>${pct(row.projected)}</strong></td><td><span class="delta-pos">+${row.gain.toFixed(1)} pp</span></td>${DATA.servers.map(server=>`<td>${pct(row.serverProjected[server.id])}</td>`).join('')}<td>${DATA.servers.map(server=>`${esc(server.name)} ${row.moved[server.id]}`).join(' &middot; ')}</td></tr>`).join('');
horizontalBars('scenario-bars',scenarios.map(row=>({label:row.name,value:row.projected})));
const focusByArea={1:'Document topology and implement a supported HA endpoint pattern.',2:'Make ETL incremental, restartable, idempotent, and failure-aware.',3:'Remove unsafe dynamic SQL and enforce structured error handling.',4:'Strengthen keys, constraints, schema design, and measured maintenance.',5:'Add schema, completeness, reconciliation, quarantine, and promotion gates.',6:'Reduce privileged access; encrypt data and backups; remove stored credentials.',7:'Enable reviewable, retained, tamper-resistant SQL Audit evidence.',8:'Assign ownership, metadata, lineage, dictionary, and glossary controls.',9:'Prove restores, move backups off-host, and test HA/DR.',10:'Enable Query Store, persistent telemetry, and actionable alerting.',11:'Route production changes through versioned, tested deployment pipelines.',12:'Persist workload trends and right-size from measured demand.',13:'Create owned runbooks, recovery procedures, and data definitions.',14:'Enable Query Store, blocking capture, and evidence-based tuning.'};
document.getElementById('recommendation-areas').innerHTML=DATA.areas.map(area=>`<tr><td>${area.number}</td><td><strong>${esc(area.name)}</strong></td><td>${areaPriorityCount(area)}</td><td>${areaSharedPriority(area)}</td><td>${areaActionCount(area)}</td><td>${esc(focusByArea[area.number])}</td></tr>`).join('');

function renderTimeline(){const rawPoints=[{label:'Current',window:'Baseline',score:estateAverage},{label:'Critical closure',window:'0-7 days',score:scenarios[0].projected},{label:'Top 10 / server',window:'By day 30',score:scenarios[2].projected},{label:'Critical + High',window:'By day 90',score:scenarios[1].projected},{label:'Score 0 closure',window:'By day 180',score:scenarios[3].projected},{label:'90% maturity',window:'6-12 month target',score:90}],points=rawPoints.map((point,index)=>({...point,score:index===0?point.score:Math.min(90,Math.max(...rawPoints.slice(0,index+1).map(item=>item.score)))})),width=1080,height=310,left=65,right=45,top=35,bottom=70,plotWidth=width-left-right,plotHeight=height-top-bottom,coordinates=points.map((point,index)=>[left+plotWidth*index/(points.length-1),top+plotHeight*(1-point.score/100)]);let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Modeled SQL remediation timeline">`;[0,25,50,75,100].forEach(tick=>{const y=top+plotHeight*(1-tick/100);svg+=`<line x1="${left}" y1="${y}" x2="${width-right}" y2="${y}" stroke="#dce2e8" stroke-dasharray="5 5"/><text x="${left-10}" y="${y+4}" text-anchor="end" font-size="10" fill="#7a8792">${tick}%</text>`});[[76,'#e31837'],[90,'#147a52']].forEach(item=>{const y=top+plotHeight*(1-item[0]/100);svg+=`<line x1="${left}" y1="${y}" x2="${width-right}" y2="${y}" stroke="${item[1]}" stroke-width="2" stroke-dasharray="7 5"/>`});svg+=`<polyline points="${coordinates.map(point=>point.join(',')).join(' ')}" fill="none" stroke="#1967a3" stroke-width="4"/>`;points.forEach((point,index)=>{const [x,y]=coordinates[index];svg+=`<circle cx="${x}" cy="${y}" r="7" fill="${index===0?'#17283a':'#fff'}" stroke="#1967a3" stroke-width="3"/><text x="${x}" y="${y-14}" text-anchor="middle" font-size="12" font-weight="700">${point.score.toFixed(1)}%</text><text x="${x}" y="${height-38}" text-anchor="middle" font-size="10.5" font-weight="700">${esc(point.label)}</text><text x="${x}" y="${height-21}" text-anchor="middle" font-size="9.5" fill="#84909a">${esc(point.window)}</text>`});document.getElementById('timeline-chart').innerHTML=svg+'</svg>';const critical=actions.filter(action=>action.severity==='Critical').length,high=actions.filter(action=>action.severity==='High').length,steps=[['0-7 days','Contain and assign','Executive sponsor, DBA, and control owners',scenarios[0].projected,[`Assign owners and dates to all ${priorityActions} priority actions.`,`Contain and evidence ${critical} Critical actions.`,`Resolve or accept ${DATA.accessIssues.length} access exceptions.`],'Critical exposure is closed or accepted and evidence locations are recorded.'],['By day 30','Deliver highest-leverage controls','DBA, Security, and Data Engineering leads',scenarios[2].projected,['Implement each server’s ten highest-priority weak controls.','Collect server-specific validation evidence.','Rerun targeted checks and reconcile the action register.'],'Changes pass technical validation and reproduce the modeled improvement.'],['By day 90','Close the priority backlog','Control owners and independent assurance',scenarios[1].projected,[`Close the remaining ${critical+high} Critical/High actions.`,`Prioritize ${actions.filter(action=>action.shared&&severityRank[action.severity]>=3).length} shared priority actions.`,`Rerun all ${DATA.servers.length} server assessments.`],'No priority item is closed without dated evidence and independent verification.'],['By day 180','Eliminate score-zero controls','Area owners and service owner',scenarios[3].projected,['Remediate every validated score-zero control.','Sequence other work by weighted area impact.','Confirm each server independently crosses Good.'],'Every credited closure has accepted evidence and no weak node is hidden by the average.'],['6-12 months','Reach 90% maturity','Service owner and governance forum',90,['Raise residual score-one controls.','Close governance, monitoring, and documentation gaps.','Review recovery, audit, alert, and capacity evidence quarterly.'],'Every server independently reaches at least 90% with current evidence.']];document.getElementById('timeline-grid').innerHTML=steps.map(step=>`<article class="step-card"><div class="step-window">${esc(step[0])}</div><h3>${esc(step[1])}</h3><div class="step-owner"><strong>Owner:</strong> ${esc(step[2])}</div><div class="step-target">${pct(step[3])} modeled</div><ul>${step[4].map(action=>`<li>${esc(action)}</li>`).join('')}</ul><div class="step-gate"><strong>Evidence gate:</strong> ${esc(step[5])}</div></article>`).join('')}
renderRadar();renderTimeline();
document.getElementById('principle-grid').innerHTML=DATA.areas.map(a=>'<article class="principle"><strong>'+a.number+'. '+esc(a.name)+'</strong><span>'+a.items+' controls weighted at '+a.weight+'% of the overall assessment.</span></article>').join('');document.getElementById('scope-summary').innerHTML='<strong>'+esc(DATA.target)+'</strong><p>Deployment mode: '+esc(DATA.deploymentMode)+'</p><p>Source workbook: '+esc(DATA.workbook)+'</p><p>Generated: '+esc(DATA.generated)+'</p>';
